<?php declare(strict_types=1);use yii\helpers\Html;FMonitor2\YiiRuntime\Assets\AuthAssetBundle::register($this);$reset=$mode==='reset';$title=$reset?'Новый пароль':'Первый пароль';$this->beginPage();?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=Html::encode($title)?> — FMonitor</title><link rel="icon" href="/pilot/assets/favicon.svg"><?php $this->head()?></head><body class="shlz-scope fm2-auth-page"><?php $this->beginBody()?><a class="fm2-skip shlz-link" href="#main-content">Перейти к содержанию</a><main class="fm2-auth-layout" id="main-content"><section class="fm2-auth-brand" aria-label="FMonitor"><img src="/pilot/assets/favicon.svg" alt="" width="56" height="56"><div><strong>FMonitor</strong><span>Управление монтажными работами</span></div></section><section class="fm2-auth-card"><div class="fm2-auth-heading"><h1><?=Html::encode($done?($reset?'Пароль изменён':'Пароль установлен'):$title)?></h1></div><?php if($done):?><p>Теперь войдите с новым паролем.</p><a class="shlz-button shlz-button--primary fm2-auth-submit" href="/pilot/login">Войти</a><?php elseif($reset&&$email===''):?><p class="fm2-auth-error" role="alert"><?=Html::encode($error)?></p><a class="shlz-button shlz-button--primary fm2-auth-submit" href="/pilot/forgot-password">Запросить восстановление заново</a><a class="fm2-auth-back" href="/pilot/login">Вернуться ко входу</a><?php else:?><form method="post" action="<?=$reset?'/pilot/reset-password':'/pilot/first-password'?>" class="fm2-auth-form"><input type="hidden" name="<?=Html::encode(Yii::$app->request->csrfParam)?>" value="<?=Html::encode(Yii::$app->request->csrfToken)?>"><input type="hidden" name="email" value="<?=Html::encode($email)?>"><?php if($reset):?><input type="hidden" name="token" value="<?=Html::encode($token)?>"><?php endif?><label class="shlz-field"><span class="shlz-field__label">Новый пароль</span><span class="shlz-field__control"><input class="shlz-input" type="password" name="password" aria-describedby="password-requirements" autocomplete="new-password" minlength="10" maxlength="200" required autofocus></span></label><label class="shlz-field"><span class="shlz-field__label">Повторите пароль</span><span class="shlz-field__control"><input class="shlz-input" type="password" name="passwordConfirmation" aria-describedby="password-requirements" autocomplete="new-password" minlength="10" maxlength="200" required></span></label><p class="fm2-auth-help" id="password-requirements">10–200 символов: строчную и заглавную латинские буквы, цифру и спецсимвол.</p><?php if($error!==''):?><p class="fm2-auth-error" role="alert"><?=Html::encode($error)?></p><?php endif?><button class="shlz-button shlz-button--primary fm2-auth-submit" type="submit">Сохранить пароль</button><a class="fm2-auth-back" href="/pilot/login">Вернуться ко входу</a></form><?php endif?></section></main><?php $this->endBody()?></body></html><?php $this->endPage()?>
